fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter().map(|s| {
        let mut lines: Vec<String> = Vec::new();
        let mut start = 0;

        // Iterate through the string to find line endings
        for (i, c) in s.char_indices() {
            if c == '\n' || (c == '\r' && (i + 1 < s.len() && s.as_bytes()[i + 1] == b'\n')) {
                // Determine the end index for the current line
                let end = if c == '\n' { i } else { i + 1 };
                let line = if keepends {
                    s[start..end + 1].to_string() // Include the line ending
                } else {
                    s[start..i].to_string() // Exclude the line ending
                };
                lines.push(line);
                start = end + 1; // Move start to the next character after the line ending
            }
        }

        // Add the last line if there's any remaining text
        if start < s.len() {
            let line = if keepends {
                s[start..].to_string() // Include the line ending
            } else {
                s[start..].to_string() // Exclude the line ending
            };
            lines.push(line);
        }

        // Ensure that the inner list is non-empty
        if lines.is_empty() {
            lines.push("".to_string()); // Fallback to a non-empty string if needed
        }

        lines
    }).collect()
}